{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C05"],
      "claim": "A close alkyne-pyridine mGlu5 ligand ([18F]2a) was shown by PET to cross the blood-brain barrier in rodents with uptake in striatum, hippocampus, and cortex, directly supporting CNS access for the query's alkyne-pyridine motif.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "Basimglurant, a fluorophenyl imidazole alkyne-pyridine mGlu5 modulator structurally related to the query, had a brain/plasma ratio of 2-3 in preclinical studies, indicating good BBB permeability for this scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "In rats, the lipophilic heteroaryl compound 16f showed a brain penetration index (AUCbrain/plasma) of 3.5, demonstrating that this class of moderately lipophilic heteroaromatic CNS agents achieves meaningful brain exposure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "MPEPy, an alkyne-pyridine mGlu5 tracer, crosses the BBB in PET studies despite being a P-gp efflux substrate, showing that efflux liability does not preclude meaningful CNS access for this chemotype.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "MPPF, a structurally distinct arylpiperazine tracer, is a P-gp substrate with low brain uptake (0.05% ID/g in rats); this negative example has low similarity to the query and does not override the alkyne-pyridine positive evidence.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Predicted pass: the query is a lipophilic imidazopyridine alkyne-pyridine mGlu5-type ligand, and multiple related analogues with direct brain-penetration measurements or brain/plasma ratios >2 support meaningful CNS access; the one low-similarity negative (MPPF) is outweighed by the consistent positive evidence.",
  "evidence_gaps": [
    "No direct brain/plasma or PET measurement exists for the exact query molecule.",
    "Efflux transporter liability of the query was not directly measured.",
    "Morgan similarities are modest (0.20-0.27), so transfer relies on shared pharmacophore rather than high structural identity."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

